import React from 'react';
import {
  Box,
  Button,
  Chip,
  LinearProgress,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import {
  CheckCircle as DoneIcon,
  EmojiEvents as TrophyIcon,
  RadioButtonUnchecked as TodoIcon,
} from '@mui/icons-material';
import { alpha, useTheme } from '@mui/material/styles';
import { Link as RouterLink } from 'react-router-dom';
import type { SectionQuest, SectionQuestBoard as QuestBoard } from '../../utils/sectionQuests';

type SectionQuestBoardProps = {
  board: QuestBoard;
  title: string;
  subtitle: string;
  completeMessage?: string;
  ariaLabel?: string;
  onFocusQuest?: (quest: SectionQuest) => void;
  primaryAction?: {
    label: string;
    onClick: () => void;
    loading?: boolean;
  };
};

const SectionQuestBoard: React.FC<SectionQuestBoardProps> = ({
  board,
  title,
  subtitle,
  completeMessage = 'All quests complete — keep going when you have new data.',
  ariaLabel,
  onFocusQuest,
  primaryAction,
}) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';

  return (
    <Paper
      variant="outlined"
      sx={{
        p: { xs: 2, sm: 2.5 },
        mb: 3,
        borderColor: alpha(theme.palette.primary.main, 0.35),
        background: `linear-gradient(135deg, ${alpha(theme.palette.success.main, isDark ? 0.12 : 0.06)} 0%, ${theme.palette.background.paper} 55%)`,
      }}
      aria-label={ariaLabel || title}
    >
      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} justifyContent="space-between" sx={{ mb: 2 }}>
        <Box>
          <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 0.5 }} flexWrap="wrap">
            <TrophyIcon color="warning" />
            <Typography variant="h6" sx={{ fontWeight: 800 }}>
              {title}
            </Typography>
            <Chip
              size="small"
              color="primary"
              label={`Level ${board.level} · ${board.levelLabel}`}
              sx={{ fontWeight: 700 }}
            />
          </Stack>
          <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 560 }}>
            {subtitle} {board.levelCaption}
          </Typography>
        </Box>
        <Box sx={{ minWidth: { sm: 160 }, textAlign: { sm: 'right' } }}>
          <Typography variant="caption" color="text.secondary">
            Quest progress
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 800 }}>
            {board.completedCount}/{board.totalCount}
          </Typography>
          <LinearProgress
            variant="determinate"
            value={board.percent}
            sx={{ mt: 0.75, height: 8, borderRadius: 999, bgcolor: alpha(theme.palette.primary.main, 0.12) }}
          />
        </Box>
      </Stack>

      <Stack spacing={1.25}>
        {board.quests.map((quest) => (
          <Paper
            key={quest.id}
            variant="outlined"
            sx={{
              p: 1.5,
              borderColor: quest.complete
                ? alpha(theme.palette.success.main, 0.45)
                : alpha(theme.palette.divider, 0.9),
              bgcolor: quest.complete
                ? alpha(theme.palette.success.main, isDark ? 0.12 : 0.05)
                : 'transparent',
            }}
          >
            <Stack direction="row" spacing={1.5} alignItems="flex-start">
              <Box sx={{ mt: 0.25 }}>
                {quest.complete ? (
                  <DoneIcon color="success" fontSize="small" />
                ) : (
                  <TodoIcon color="disabled" fontSize="small" />
                )}
              </Box>
              <Box sx={{ flex: 1, minWidth: 0 }}>
                <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
                  <Typography variant="subtitle2" fontWeight={700}>
                    {quest.title}
                  </Typography>
                  {quest.complete ? <Chip size="small" color="success" label="Done" /> : null}
                </Stack>
                <Typography variant="body2" color="text.secondary" sx={{ mt: 0.35 }}>
                  {quest.description}
                </Typography>
              </Box>
              {!quest.complete && primaryAction && board.nextQuest?.id === quest.id ? (
                <Button
                  size="small"
                  variant="contained"
                  onClick={primaryAction.onClick}
                  disabled={primaryAction.loading}
                >
                  {primaryAction.loading ? 'Working…' : primaryAction.label}
                </Button>
              ) : !quest.complete && quest.path ? (
                <Button
                  size="small"
                  variant="outlined"
                  component={RouterLink}
                  to={quest.path}
                >
                  {quest.ctaLabel || 'Do this'}
                </Button>
              ) : !quest.complete && onFocusQuest ? (
                <Button size="small" variant="outlined" onClick={() => onFocusQuest(quest)}>
                  {quest.ctaLabel || 'Do this'}
                </Button>
              ) : null}
            </Stack>
          </Paper>
        ))}
      </Stack>

      {board.nextQuest ? (
        <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1.5 }}>
          Up next: <strong>{board.nextQuest.title}</strong>
        </Typography>
      ) : (
        <Typography variant="caption" color="success.main" display="block" sx={{ mt: 1.5, fontWeight: 700 }}>
          {completeMessage}
        </Typography>
      )}
    </Paper>
  );
};

export default SectionQuestBoard;
